#!/usr/bin/env python3
"""Reproduce the CLI fallback PNG from the Flutter launcher's tracked icon."""
import argparse
from hashlib import sha256
from pathlib import Path

root = Path(__file__).resolve().parent.parent
asset = Path('src/UI/macos/Runner/Assets.xcassets/AppIcon.appiconset/app_icon_256.png')
target = root / 'src/default_game_icon.inc'
data = (root / asset).read_bytes()
lines = [
    '// Generated by scripts/embed_default_game_icon.py; do not edit.',
    '// Source: ' + asset.as_posix(),
    '// SHA256: ' + sha256(data).hexdigest(),
    'constexpr uint8_t default_game_icon_png[] = {',
]
lines += ['    ' + ', '.join('0x%02x' % byte for byte in data[i:i+16]) + ','
          for i in range(0, len(data), 16)]
expected = '\n'.join(lines + ['};', ''])
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true', help='fail if the embedded icon is stale')
args = parser.parse_args()
if args.check:
    if not target.exists() or target.read_text() != expected:
        raise SystemExit('Embedded game icon is stale; run scripts/embed_default_game_icon.py')
else:
    target.write_text(expected)
